import { argon2id } from 'hash-wasm';
import { randomBytes, timingSafeEqual } from 'node:crypto';

/**
 * Password hashing in PHC-format argon2id.
 *
 * Port of backend/internal/auth/password.go. The verification must accept
 * exactly the hashes the Go implementation wrote into `users.password_hash` —
 * password-vectors.json was generated by that code (backend/tools/vectors) and
 * the test in password.test.ts is what proves compatibility. Parameters are
 * read from each stored hash, so raising the cost later will not invalidate
 * existing passwords.
 */

const ARGON_VERSION = 19;
const ARGON_TIME = 3;
const ARGON_MEMORY = 64 * 1024; // 64 MiB
const ARGON_THREADS = 4;
const ARGON_KEY_LEN = 32;
const SALT_LEN = 16;

export const DUMMY_PASSWORD = 'katafa-nonexistent-account-placeholder';

/** base64 with the padding removed — Go's base64.RawStdEncoding. */
function b64raw(buffer: Buffer): string {
  return buffer.toString('base64').replace(/=+$/, '');
}

interface ParsedHash {
  time: number;
  memory: number;
  threads: number;
  salt: Buffer;
  key: Buffer;
}

/**
 * Parses a PHC argon2id string. Anything malformed returns null and is
 * treated as a failed login rather than a server error, so a corrupt row
 * cannot be used to distinguish accounts.
 */
function parsePHC(encoded: string): ParsedHash | null {
  const parts = encoded.split('$');
  if (parts.length !== 6 || parts[1] !== 'argon2id') return null;
  if (parts[2] !== `v=${ARGON_VERSION}`) return null;

  const params = /^m=(\d+),t=(\d+),p=(\d+)$/.exec(parts[3]);
  if (!params) return null;

  let salt: Buffer;
  let key: Buffer;
  try {
    salt = Buffer.from(parts[4], 'base64');
    key = Buffer.from(parts[5], 'base64');
  } catch {
    return null;
  }
  if (salt.length === 0 || key.length === 0) return null;

  return {
    memory: Number(params[1]),
    time: Number(params[2]),
    threads: Number(params[3]),
    salt,
    key,
  };
}

async function derive(
  password: string,
  salt: Buffer,
  memory: number,
  time: number,
  threads: number,
  keyLen: number,
): Promise<Buffer> {
  const hex = await argon2id({
    password,
    salt,
    parallelism: threads,
    iterations: time,
    memorySize: memory,
    hashLength: keyLen,
    outputType: 'hex',
  });
  return Buffer.from(hex, 'hex');
}

export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(SALT_LEN);
  const key = await derive(password, salt, ARGON_MEMORY, ARGON_TIME, ARGON_THREADS, ARGON_KEY_LEN);
  return `$argon2id$v=${ARGON_VERSION}$m=${ARGON_MEMORY},t=${ARGON_TIME},p=${ARGON_THREADS}$${b64raw(salt)}$${b64raw(key)}`;
}

/**
 * Reports whether the password matches the stored hash.
 *
 * Malformed hashes return false — same observable behaviour as Go's
 * ErrInvalidHash, which login treats as a failed authentication. The
 * comparison runs in constant time.
 */
export async function verifyPassword(password: string, encoded: string): Promise<boolean> {
  const parsed = parsePHC(encoded);
  if (!parsed) return false;

  const got = await derive(password, parsed.salt, parsed.memory, parsed.time, parsed.threads, parsed.key.length);
  if (got.length !== parsed.key.length) return false;
  return timingSafeEqual(got, parsed.key);
}

let dummy: Promise<string> | null = null;

/**
 * The placeholder hash verified against when an email does not exist, so a
 * login attempt costs the same whether or not the account is real. Without
 * it, response time enumerates accounts.
 */
export function dummyHash(): Promise<string> {
  if (!dummy) dummy = hashPassword(DUMMY_PASSWORD);
  return dummy;
}
